	For all $x, z \in \F_q^m$, $\alpha, \beta \in \F_q$, and
	$\hilb \in \{\hilb_{\mathsf{A}}, \hilb_{\mathsf{B}}\}$ there exists a
	projective measurement
	$\{\hat{Q}^{x,z,\alpha,\beta}_{c}\}_{c \in \F_q}$ acting on
	$\hilb \ot (\C^q)^{\ot M}$ such that the following holds, where
	$\delta_Q$ is the function of Lemma~\ref{lem:qld-4-10}:
	\begin{enumerate}
		\item (\textbf{Self-consistency}) On average over uniformly random
		$(x, z, \alpha, \beta) \in \F_q^{2m+2}$,
		\begin{equation}
			\label{eq:qld-4-12-self-cons}
			(\hat{Q}^{x,z,\alpha,\beta}_{c})_{\mathsf{A}\mathsf{A}'}
			\approx_{\delta_Q}
			(\hat{Q}^{x,z,\alpha,\beta}_{c})_{\mathsf{B}\mathsf{A}''}\,.
		\end{equation}
		\item (\textbf{Consistency with $\hat{M}$}) On average over uniformly
		random $(x, z, \alpha, \beta) \in \F_q^{2m+2}$,
		\begin{gather}
			\label{eq:qld-4-12-cons-m-hat}
			(\hat{Q}^{x,z,\alpha,\beta}_{c})_{\mathsf{A}\mathsf{A}'}
			\approx_{\delta_Q}
			\Big( \sum_{\substack{a,b:\\ \alpha a + \beta b = c}}
			\hat{M}^{(\mathrm{Point},X),x}_{a} \,
			\hat{M}^{(\mathrm{Point},Z),z}_{b}
			\Big)_{\mathsf{B}\mathsf{A}''}\,, \\
			\label{eq:qld-4-12-cons-m-hat2}
			(\hat{Q}^{x,z,\alpha,\beta}_{c})_{\mathsf{A}\mathsf{A}'}
			\approx_{\delta_Q}
			\Big( \sum_{\substack{a,b:\\ \alpha a + \beta b = c}}
			\hat{M}^{(\mathrm{Point},Z),z}_{b} \,
			\hat{M}^{(\mathrm{Point},X),x}_{a}
			\Big)_{\mathsf{B}\mathsf{A}''}\,.
		\end{gather}
	\end{enumerate}
	Furthermore, all symmetric equivalents of these approximations also hold.
\end{lemma}
\begin{proof}
	\uses{lem:qld-4-10, lem:qld-affine-distance-contraction}
	Define
	$\hat{Q}^{x,z,\alpha,\beta}_{c}
	= \sum_{a,b \,:\, \alpha a + \beta b = c} \hat{Q}^{x,z}_{a,b}$,
	a coarse-graining of the projective measurement of
	Lemma~\ref{lem:qld-4-10}, hence itself projective. For each $(x,z)$,
	the joint measurement and both ordered product families have total
	identity: completeness gives
	\[
		\sum_{a,b}\hat{M}^{(\mathrm{Point},X),x}_a
		\hat{M}^{(\mathrm{Point},Z),z}_b
		=\Big(\sum_a\hat{M}^{(\mathrm{Point},X),x}_a\Big)
		 \Big(\sum_b\hat{M}^{(\mathrm{Point},Z),z}_b\Big)=\Id,
	\]
	and the same calculation holds in the reverse order. Register placement
	preserves sums and identity, so the compared families have equal totals
	for every opposite placement. Apply
	Lemma~\ref{lem:qld-affine-distance-contraction} to each of the three
	comparisons of Lemma~\ref{lem:qld-4-10}. Uniform sampling of
	$(x,z,\alpha,\beta)$ samples $(x,z)$ and both coefficients independently,
	so the averaged squared distances retain their $\delta_Q$ bounds,
	including all symmetric equivalents. This argument presupposes the
	joint measurements whose existence is the separate construction in
	Lemma~\ref{lem:qld-4-10}.
\end{proof}

